                        # Doubled quote - represents a single quote
                        field += '"'
                        i += 1
                    else:
                        # End of quoted field
                        if i < len(line) and line[i] != ',':
                            # Closing quote not followed by comma or end of line
                            return None
                        fields.append(field)
                        if i < len(line):
                            i += 1  # Skip the comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
